build(a, snap) {
    const M = a.m.map((r) => r.slice()), n = M.length; let rowsDone = 0, phase = 1;
    const view = (p, q) => [{ t: "grid", label: "matrix", rows: M.map((r, i) => r.map((v, j) => ({ v, cls: (p && p[0] === i && p[1] === j) || (q && q[0] === i && q[1] === j) ? "a" : i < rowsDone ? "k" : phase === 1 && i === j ? "e" : "" }))) }];
    snap("开始", "第一步：沿主对角线（左上到右下）翻转。对角线上的数不动。", view());
    for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
      [M[i][j], M[j][i]] = [M[j][i], M[i][j]];
      snap("转置", `交换 matrix[${i}][${j}] 和 matrix[${j}][${i}]，它们关于对角线对称。`, view([i, j], [j, i]));
    }
    phase = 2;
    snap("转置完成", "现在原来的每一行变成了一列。第二步：把每一行左右翻转。", view());
    for (let i = 0; i < n; i++) {
      M[i].reverse(); rowsDone = i + 1;
      snap("翻转每一行", `第 ${i} 行左右翻转，变成 [${M[i].join(", ")}]。`, view());
    }
    snap("完成", "两步做完，矩阵顺时针旋转了 90 度。", view(), { kind: "ok", ans: M });
  }
